import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("Create a vendor", { tag: "@VEN-01" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const name = uniqueName("Acme Freight");
    const contactEmail = "ops@acmefreight.example";

    // Act
    const response = await member.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: contactEmail },
    });

    // Assert
    expect(response.status()).toBe(201);
    const vendor = await response.json();
    expect(vendor.id).toBeTruthy();
    expect(vendor.name).toBe(name);
    expect(vendor.category).toBe("logistics");
    expect(vendor.contact_email).toBe(contactEmail);
    expect(vendor.status).toBe("draft");

    const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
    expect(auditResponse.status()).toBe(200);
    const trail = await auditResponse.json();
    const actions = (trail.items as Array<{ action: string }>).map((event) => event.action);
    expect(actions).toContain("vendor.created");
  });
});
